import 'package:equatable/equatable.dart';
import 'package:sehatak/core/models/eye/eye_models.dart';
class EyeState extends Equatable { final bool isLoading; final List<EyeDoctor> doctors; final List<EyeClinic> clinics; final List<EyeTip> tips; final List<EyeHospital> hospitals; final String? errorMessage; const EyeState({this.isLoading=false,this.doctors=const [],this.clinics=const [],this.tips=const [],this.hospitals=const [],this.errorMessage}); EyeState copyWith({bool? isLoading,List<EyeDoctor>? doctors,List<EyeClinic>? clinics,List<EyeTip>? tips,List<EyeHospital>? hospitals,String? errorMessage,bool clearError=false})=>EyeState(isLoading:isLoading??this.isLoading,doctors:doctors??this.doctors,clinics:clinics??this.clinics,tips:tips??this.tips,hospitals:hospitals??this.hospitals,errorMessage:clearError?null:(errorMessage??this.errorMessage)); @override List<Object?> get props=>[isLoading,doctors,clinics,tips,hospitals,errorMessage]; }
